# Fixed rule: only shrink if num_blocks >= 2 (meaning at least one internal gap)
def row_transform(row, w):
    positions = [c for c, v in enumerate(row) if v != 0]

    if not positions:
        return row[:]

    # Count blocks (runs of consecutive non-zeros)
    num_blocks = 0
    start = None
    for c in range(w):
        if row[c] != 0:
            if start is None:
                start = c
        else:
            if start is not None:
                num_blocks += 1
                start = None
    if start is not None:
        num_blocks += 1  # The last block

    if num_blocks >= 2:  # Has internal gaps, needs fill + shrink
        min_col, max_col = positions[0], positions[-1]
        result = [0] * w
        for c in range(min_col, max_col + 1):
            result[c] = 4
        new_left = min_col + 1
        new_right = max_col - 1
        for c in range(w):
            if c < new_left or c > new_right:
                result[c] = 0
        return result

    # No internal gaps, return unchanged
    return row[:]

